import{_ as t,o,c as a,a2 as l}from"./chunks/framework.Crpw6aS5.js";const i=JSON.parse('{"title":"1983年 · 商誉解密与B夫人传奇","description":"","frontmatter":{},"headers":[],"relativePath":"05_quotes/by-year/1983年.md","filePath":"05_quotes/by-year/1983年.md"}'),r={name:"05_quotes/by-year/1983年.md"};function s(c,e,u,h,_,b){return o(),a("div",null,[...e[0]||(e[0]=[l('<h1 id="_1983年-·-商誉解密与b夫人传奇" tabindex="-1">1983年 · 商誉解密与B夫人传奇 <a class="header-anchor" href="#_1983年-·-商誉解密与b夫人传奇" aria-label="Permalink to &quot;1983年 · 商誉解密与B夫人传奇&quot;">​</a></h1><blockquote><p>我们形式上是公司，但态度上是合伙人。查理和我把你们股东看作合伙人，我们自己是管理合伙人。我们不认为公司本身是我们业务资产的最终所有者，相反，我们把公司看作一个管道，让我们股东持有资产。——巴菲特（53岁）</p></blockquote><p>本页收录1983年致股东信中的经典语录。这一年巴菲特收购了内布拉斯加家具城，完整阐述了商誉、会计与经济价值的关系，提出在通胀年代&quot;经济商誉就是不断馈赠的礼物&quot;。</p><hr><h2 id="核心金句" tabindex="-1">核心金句 <a class="header-anchor" href="#核心金句" aria-label="Permalink to &quot;核心金句&quot;">​</a></h2><blockquote><p>我们形式上是公司，但态度上是合伙人。查理和我把你们股东看作合伙人，我们自己是管理合伙人。</p></blockquote><blockquote><p>我们的长期经济目标是最大化每股内在商业价值的年均增长率。我们不用规模衡量伯克希尔的经济重要性或表现，我们用每股进步衡量。</p></blockquote><blockquote><p>会计后果不会影响我们的经营或资本配置决策。如果收购成本差不多，我们宁愿买2美元不反映在会计准则上的盈利，也不愿意买1美元能报告的盈利。</p></blockquote><blockquote><p>我们很少借很多债，借钱也会尽量安排长期固定利率。我们会拒绝好机会，也不会过度杠杆我们的资产负债表。</p></blockquote><blockquote><p>我们会定期用结果检验保留盈利是否明智。我们的测试标准是：随着时间推移，每保留1美元盈利，是否至少给股东带来1美元的市场价值。</p></blockquote><blockquote><p>我们只有在拿到对等商业价值的时候才会发行股票。这条规则适用于所有发行形式——并购、公开发行、债转股、股票期权、可转换证券。</p></blockquote><blockquote><p>不管价格多低，我们完全没兴趣出售伯克希尔拥有的好企业，我们也很不情愿卖差企业，只要它还能至少产生一些现金流，只要我们对管理层和劳资关系还满意。</p></blockquote><blockquote><p>我们对你 reporting 会非常坦诚，强调评估企业价值重要的优缺点。我们告诉你我们自己想知道的商业事实，如果我们位置互换。</p></blockquote><blockquote><p>评估一家企业的时候，我经常问自己一个问题：如果我有足够资本和人手，我愿意和它竞争吗？我宁愿和灰熊摔跤，也不愿意和B夫人跟她的后代竞争。</p></blockquote><blockquote><p>在通胀年代，<strong>商誉就是不断馈赠的礼物</strong>。</p></blockquote><hr><h2 id="本年背景" tabindex="-1">本年背景 <a class="header-anchor" href="#本年背景" aria-label="Permalink to &quot;本年背景&quot;">​</a></h2><p>1983年伯克希尔哈撒韦每股净资产从737.43美元涨到975.83美元，涨幅32%，ROE约19%。完成了收购内布拉斯加家具城90%股份的交易，B夫人90岁依然担任董事长。巴菲特在信中完整阐述了商誉、会计与经济价值的关系：经济商誉在通胀年代会不断增值，因为只需要很少有形资产就能产生高回报。同时提出十二条合伙原则，强调以合伙人心态经营公司。</p><hr><h2 id="深入阅读" tabindex="-1">深入阅读 <a class="header-anchor" href="#深入阅读" aria-label="Permalink to &quot;深入阅读&quot;">​</a></h2><h2 id="_01-letters-1983年-翻译-·-01-letters-1983年-核心总结-·-01-letters-1983年-思维导图" tabindex="-1"><a href="/01_letters/1983年/翻译.html">01_letters/1983年/翻译</a> · <a href="/01_letters/1983年/核心总结.html">01_letters/1983年/核心总结</a> · <a href="/01_letters/1983年/思维导图.html">01_letters/1983年/思维导图</a> <a class="header-anchor" href="#_01-letters-1983年-翻译-·-01-letters-1983年-核心总结-·-01-letters-1983年-思维导图" aria-label="Permalink to &quot;[[→ 原文翻译|01_letters/1983年/翻译]] · [[→ 核心总结|01_letters/1983年/核心总结]] · [[→ 思维导图|01_letters/1983年/思维导图]]&quot;">​</a></h2><h2 id="关键原文出处" tabindex="-1">关键原文出处 <a class="header-anchor" href="#关键原文出处" aria-label="Permalink to &quot;关键原文出处&quot;">​</a></h2><ul><li><a href="/01_letters/1983年/翻译.html">/01_letters/1983年/翻译</a></li></ul>',23)])])}const p=t(r,[["render",s]]);export{i as __pageData,p as default};
